import React, { useRef } from 'react'
import { useFrame } from 'react-three-fiber'
import lerp from 'lerp'

/** Flat XY pan only — no rotation, no depth. Applied outside inspect orbit. */
export default function MascotInspect({ inspectRef, children }) {
  const panRef = useRef()
  const smooth = useRef({ posX: 0, posY: 0 })

  useFrame(() => {
    if (!panRef.current || !inspectRef?.current) return
    const t = inspectRef.current
    const targetX = t.posX ?? 0
    const targetY = t.posY ?? 0

    if (t.snap || t.dragging) {
      smooth.current.posX = targetX
      smooth.current.posY = targetY
    } else if (!t.enabled) {
      smooth.current.posX = lerp(smooth.current.posX, 0, 0.12)
      smooth.current.posY = lerp(smooth.current.posY, 0, 0.12)
    } else {
      smooth.current.posX = lerp(smooth.current.posX, targetX, 0.28)
      smooth.current.posY = lerp(smooth.current.posY, targetY, 0.28)
    }

    // Explicit plane translation — never touch z/rotation here.
    panRef.current.position.x = smooth.current.posX
    panRef.current.position.y = smooth.current.posY
    panRef.current.position.z = 0
    panRef.current.rotation.set(0, 0, 0)
  })

  return <group ref={panRef}>{children}</group>
}
